-- Create temporary archive table with all original columns plus CACI score
CREATE TEMP TABLE archived_coordination (LIKE coordinationandevaluation);

ALTER TABLE archived_coordination ADD COLUMN caciscore numeric(10,4);

INSERT INTO archived_coordination
SELECT 
    *,
    ROUND(CAST(
        (CAST(partnerorgs AS numeric) / 10.0) * 
        CASE coordeffectlvl WHEN 'Low' THEN 1 WHEN 'Medium' THEN 2 WHEN 'High' THEN 3 ELSE 0 END * 
        ((CASE infosharingstate WHEN 'Poor' THEN 1 WHEN 'Limited' THEN 2 WHEN 'Effective' THEN 3 ELSE 0 END + 1) / 3.0)
    AS numeric), 4)
FROM coordinationandevaluation;

DELETE FROM coordinationandevaluation;

CREATE TEMP TABLE archived_coordination AS SELECT * FROM coordinationandevaluation;
ALTER TABLE archived_coordination ADD COLUMN caciscore numeric(10,4);
UPDATE archived_coordination SET caciscore = ROUND(CAST((CAST(partnerorgs AS numeric) / 10.0) * CASE coordeffectlvl WHEN 'Low' THEN 1 WHEN 'Medium' THEN 2 WHEN 'High' THEN 3 ELSE 0 END * ((CASE infosharingstate WHEN 'Poor' THEN 1 WHEN 'Limited' THEN 2 WHEN 'Effective' THEN 3 ELSE 0 END + 1) / 3.0) AS numeric), 4);
DELETE FROM coordinationandevaluation;

